'use strict';
// Photo-led workspace. All records here remain browser-local sample data.
let workTab='photos',catalogGrouped=true,catalogQuery='',viewerIndex=0,decisionMode='partial',reviewSelection=new Set(),reviewNote='',catalogOpen=true;
const priorSaveField=saveField,priorSaveCheck=saveCheck,priorSaveEquipment=saveEquipment,priorAddEquipment=addEquipment,priorRemoveEquipment=removeEquipment,priorCustomSave=saveCustomAnswer,priorUpload=uploadForSite,priorRemovePhoto=removePhoto,priorCategory=setPhotoCategory;
const fieldSections={general:['siteType','operator','towerHeight','surveyDate','access','generalNotes'],civil:['civilNotes'],electrical:['voltage','currentR','currentY','currentB','electricalNotes'],power:['capacity','battery','generator','solar','powerNotes'],shared:['dcVoltage','powerSource']};
function reviewSections(s=site()){return s.templateSnapshot?s.templateSnapshot.definition.sections.map(x=>({id:x.id,title:x.title,group:x.group||'Checklist',fields:x.fields})):sections.filter(x=>x[0]!=='submission').map(x=>({id:x[0],title:x[2],group:['power','electrical'].includes(x[0])?'Power & electrical':'Site survey'}));}
function sectionLocked(id,s=site()){return s.status==='Approved'||!!s.sectionApprovals?.[id];}
function currentSectionId(){return site().templateSnapshot?reviewSections()[customSection]?.id:section;}
function editableSection(id,s=site()){if(sectionLocked(id,s)){toast('This section is approved and locked');return false;}return true;}
function legacyFieldLocked(k){const ids=fieldSections.shared.includes(k)?['electrical','power']:Object.entries(fieldSections).filter(([_,v])=>v.includes(k)).map(([id])=>id);return ids.some(id=>sectionLocked(id));}
saveField=function(k,v){if(!legacyFieldLocked(k))priorSaveField(k,v);else toast('This field belongs to an approved section');};
saveCheck=function(k,v){const id=['earthing','labels'].includes(k)?'electrical':'civil';if(editableSection(id))priorSaveCheck(k,v);};
saveEquipment=function(i,k,v){if(editableSection('equipment'))priorSaveEquipment(i,k,v);};
addEquipment=function(){if(editableSection('equipment'))priorAddEquipment();};
removeEquipment=function(i){if(editableSection('equipment'))priorRemoveEquipment(i);};
saveCustomAnswer=function(fid,v){const sec=reviewSections().find(x=>x.fields?.some(f=>f.id===fid));if(sec&&editableSection(sec.id))priorCustomSave(fid,v);};
function photoSection(p,s=site()){if(p.sectionId)return p.sectionId;if(p.fieldId)return reviewSections(s).find(x=>x.fields?.some(f=>f.id===p.fieldId))?.id;return ({Civil:'civil',Tower:'equipment',Electrical:'electrical',Power:'power',General:'general'})[p.category]||'evidence';}
removePhoto=function(id,i){const s=data.sites.find(x=>x.id===id);if(s&&s.photos[i]&&editableSection(photoSection(s.photos[i],s),s))priorRemovePhoto(id,i);};
setPhotoCategory=function(id,i,c){const s=data.sites.find(x=>x.id===id);if(!s?.photos[i])return;const next=({Civil:'civil',Tower:'equipment',Electrical:'electrical',Power:'power',General:'general'})[c];if(editableSection(photoSection(s.photos[i],s),s)&&editableSection(next,s))priorCategory(id,i,c);};
uploadForSite=function(){const s=site(),id=currentSectionId();if(!editableSection(id))return;if(s.templateSnapshot&&!window.customEvidenceField){const sec=reviewSections().find(x=>x.id===id);const f=sec?.fields?.find(f=>['inspection','photo'].includes(f.type));window.customEvidenceField=f?.id||'';}window.workspaceUploadSection=id;priorUpload();};
// Tag uploads with the section selected when the file picker was opened, even across navigation.
const uploadNode=document.getElementById('photo-input');
// The original reader is replaced to enforce section locks at completion too.
const uploadReplacement=uploadNode.cloneNode?uploadNode.cloneNode(true):null;
if(uploadReplacement){uploadNode.replaceWith(uploadReplacement);uploadReplacement.addEventListener('change',async function(){const s=site(),sid=window.workspaceUploadSection||currentSectionId(),fid=window.customEvidenceField||'';let added=0;for(const file of this.files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Choose JPG, PNG or WebP under 5 MB');continue;}const src=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve(null);r.readAsDataURL(file);});if(!src||sectionLocked(sid,s))continue;s.photos.push({name:file.name,src,category:reviewSections(s).find(x=>x.id===sid)?.title||'General',fieldId:fid,sectionId:sid});if(!persist()){s.photos.pop();break;}added++;}this.value='';window.customEvidenceField='';window.workspaceUploadSection='';updateProgress();persist();render();toast(added+' photographs saved on this device');});}
function openCatalogSection(i){const sec=reviewSections()[i];if(!sec)return;if(site().templateSnapshot)customSection=i;else section=sec.id;viewerIndex=0;render();}
openSite=function(id,part='general'){selected=id;section=part;customSection=0;viewerIndex=0;reviewSelection.clear();reviewNote='';workTab=part==='submission'?'checklist':'photos';go('workspace');};
function setWorkTab(tab){workTab=tab;render();}
function pickDecision(mode){decisionMode=mode;render();}
function selectReviewSection(id,on){on?reviewSelection.add(id):reviewSelection.delete(id);render();const d=document.querySelector('.section-dropdown');if(d)d.open=true;}
function selectReviewAll(on){reviewSelection=new Set(on?reviewSections().filter(x=>!sectionLocked(x.id)).map(x=>x.id):[]);render();const d=document.querySelector('.section-dropdown');if(d)d.open=true;}
function catalog(){const s=site(),all=reviewSections(),groups=[...new Set(all.map(x=>x.group))];const item=(sec,i)=>`<button class="catalog-item ${currentSectionId()===sec.id?'active':''}" onclick="openCatalogSection(${i})">${I('file')}<span>${E(sec.title)}</span>${sectionLocked(sec.id)?I('shield'):''}</button>`;const matches=sec=>(sec.title+' '+sec.group).toLowerCase().includes(catalogQuery.toLowerCase());return `<aside class="catalog ${catalogOpen?'':'catalog-hidden'}"><div class="catalog-heading"><h2>Site catalog</h2><button class="iconbtn" onclick="catalogOpen=false;render()" aria-label="Hide catalog">${I('close')}</button></div><div class="project-tree"><details open><summary>${I('folder')} ${E(s.project)}</summary><details open><summary>${I('folder')} ${E(s.subproject||s.region||'Central region')}</summary><select aria-label="Select Site ID" onchange="openSite(this.value)">${visibleSites().filter(x=>x.project===s.project).map(x=>`<option ${x.id===s.id?'selected':''}>${E(x.id)}</option>`).join('')}</select></details></details></div><form class="catalog-search" onsubmit="event.preventDefault();catalogQuery=this.querySelector('input').value;render()">${I('search')}<input aria-label="Find section" placeholder="Find section…" value="${E(catalogQuery)}"><button type="submit" aria-label="Search sections">${I('arrow')}</button></form><div class="catalog-tools"><button class="${catalogGrouped?'chosen':''}" onclick="catalogGrouped=true;render()">${I('folder')}Group</button><button class="${!catalogGrouped?'chosen':''}" onclick="catalogGrouped=false;render()">Ungroup</button></div><p class="catalog-label">CHECKLIST</p><nav aria-label="Checklist sections">${catalogGrouped?groups.map(g=>`<details open class="catalog-group"><summary>${I('folder')}${E(g)}</summary>${all.map((sec,i)=>matches(sec)&&sec.group===g?item(sec,i):'').join('')}</details>`).join(''):all.map((sec,i)=>matches(sec)?item(sec,i):'').join('')}</nav><button class="catalog-item" onclick="workTab='checklist';section='submission';customSection=reviewSections().length;render()">${I('clipboard')}<span>Review & submit</span></button><div class="catalog-foot">${all.length} sections · ${s.progress}% complete<br>Shield marks an approved section.</div></aside>`;}
function decisionPanel(){const s=site(),reviewer=role!=='Engineer',canReview=['Awaiting review','Under Review','Partially approved'].includes(s.status),count=[...reviewSelection].filter(id=>reviewSections().some(x=>x.id===id)&&!sectionLocked(id)).length;if(!reviewer)return `<div class="engineer-note">${I('shield')} ${s.status==='Partially approved'?'Approved sections are locked. Complete the remaining sections.':'Complete your checklist, attach evidence, then submit for review.'}</div>`;return `<section class="decision-panel compact-decision" aria-label="Survey review decision"><div class="review-row"><label class="compact-observation"><span>Observation</span><input aria-label="Review observation" placeholder="Observation or rejection reason…" value="${E(reviewNote)}" oninput="reviewNote=this.value"></label><button class="btn" ${canReview?'':'disabled'} onclick="recordWorkspaceDecision('changes')">Request changes</button><div class="decision-options"><div>${[['approve','Full Approve'],['partial','Partial Approve'],['reject','Full Reject']].map(([mode,label])=>`<button class="btn ${mode} ${decisionMode===mode?'selected':''}" aria-pressed="${decisionMode===mode}" onclick="pickDecision('${mode}')">${label}</button>`).join('')}</div></div></div><div class="review-row review-selection-row">${decisionMode==='partial'?`<details class="section-dropdown"><summary>Select sections <span>${count} selected</span></summary><div class="section-popover"><div class="row between"><strong>Sections to approve</strong><button class="text-action" onclick="selectReviewAll(true)">Select all</button><button class="text-action" onclick="selectReviewAll(false)">Clear selection</button></div><div class="section-choices">${reviewSections().map(x=>`<label><input type="checkbox" ${sectionLocked(x.id)?'disabled checked':reviewSelection.has(x.id)?'checked':''} onchange="selectReviewSection('${E(x.id)}',this.checked)"><span>${E(x.title)}</span>${sectionLocked(x.id)?I('shield'):''}</label>`).join('')}</div></div></details>`:'<span class="decision-hint">'+(decisionMode==='reject'?'Rejection reason required':'Approve all applicable sections')+'</span>'}<span class="decision-hint">${canReview?'Approved sections locked · Remaining sections pending':'Submit the survey to enable review'}</span><button class="btn ${decisionMode==='reject'?'danger':'primary'}" ${canReview?'':'disabled'} onclick="recordWorkspaceDecision(decisionMode)">${decisionMode==='partial'?'Approve selected sections':decisionMode==='approve'?'Confirm full approval':'Confirm full rejection'}</button></div></section>`;}
function requiredMissingInSections(s,ids){if(!s.templateSnapshot)return [];const sub={...s,templateSnapshot:{...s.templateSnapshot,definition:{sections:s.templateSnapshot.definition.sections.filter(x=>ids.includes(x.id))}}};return customMissing(sub);}
function recordWorkspaceDecision(action){const s=site();if(role==='Engineer'){toast('Only a reviewer can record a decision');return false;}if(!['Awaiting review','Under Review','Partially approved'].includes(s.status)){toast('Submit the survey before recording a review decision');return false;}const all=reviewSections(s),note=reviewNote.trim();let ids=action==='approve'?all.map(x=>x.id):[...reviewSelection].filter(id=>all.some(x=>x.id===id)&&!sectionLocked(id));if(['changes','reject'].includes(action)&&!note){toast('Add a reason before returning or rejecting the survey');return false;}if(action==='partial'&&!ids.length){toast('Select at least one pending section');return false;}if(['approve','partial'].includes(action)){const missing=requiredMissingInSections(s,ids);if(missing.length){toast('Complete required fields in the selected sections: '+missing.slice(0,2).join(', '));return false;}}
const old=cloneTemplateValue(s),now=new Date().toISOString();s.sectionApprovals=s.sectionApprovals||{};if(action==='approve'||action==='partial'){for(const id of ids)s.sectionApprovals[id]={by:role,time:now};s.status=all.every(x=>s.sectionApprovals[x.id])?'Approved':'Partially approved';if(s.status==='Approved')s.progress=100;}else if(action==='reject'){s.sectionApprovals={};s.status='Rejected';}else s.status='Changes requested';s.comments.push({by:role,text:(action==='partial'?'Partial approval: '+all.filter(x=>ids.includes(x.id)).map(x=>x.title).join(', '):action==='approve'?'Full approval':action==='reject'?'Full rejection':'Changes requested')+(note?' — '+note:''),action,sections:ids,time:now});if(!persist()){Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,old);return false;}reviewSelection.clear();reviewNote='';render();toast(s.status==='Approved'?'Survey approved and locked':s.status==='Partially approved'?'Selected sections approved and locked':s.status==='Rejected'?'Survey rejected; reason recorded':'Changes requested; approved sections remain locked');return true;}
reviewSite=function(id,action){if(role==='Engineer'){toast('Only a reviewer can record a decision');return;}openSite(id);decisionMode='partial';render();};
commitReview=function(){const note=document.getElementById('review-comment')?.value;if(note)reviewNote=note;const action=document.getElementById('review-action')?.value||decisionMode;return recordWorkspaceDecision(action);};
function workspacePhotos(){const s=site(),id=currentSectionId(),photos=s.photos.filter(p=>photoSection(p,s)===id||id==='evidence'),n=photos.length;viewerIndex=Math.min(Math.max(viewerIndex,0),Math.max(n-1,0));const p=photos[viewerIndex];return `<section class="photo-workspace"><div class="photo-toolbar"><div><h2>${E(reviewSections().find(x=>x.id===id)?.title||'Site photographs')}</h2><p>${p?E(p.name):'Illustrative image · upload your own section evidence'}</p></div><button class="btn" ${sectionLocked(id)?'disabled':''} onclick="uploadForSite()">${I('upload')}Add photos</button></div><div class="large-photo" id="large-photo"><img src="${E(p?.src||'assets/towers.jpg')}" alt="${E(p?.name||'Illustrative telecom tower, not survey evidence')}"><span class="photo-count">${n?viewerIndex+1+' / '+n:'DEMO IMAGE · NOT EVIDENCE'}</span><button class="fullscreen" aria-label="Open photo fullscreen" onclick="fullscreenPhoto()">${I('external')}</button>${n>1?`<button class="photo-prev" aria-label="Previous photo" onclick="viewerIndex=(viewerIndex-1+${n})%${n};render()">${I('back')}</button><button class="photo-next" aria-label="Next photo" onclick="viewerIndex=(viewerIndex+1)%${n};render()">${I('arrow')}</button>`:''}</div><div class="photo-strip">${photos.map((p,i)=>`<button class="${i===viewerIndex?'active':''}" onclick="viewerIndex=${i};render()" aria-label="View ${E(p.name)}"><img src="${E(p.src)}" alt="${E(p.name)}"></button>`).join('')||'<span>No evidence uploaded for this section. The demonstration image is excluded from completion and exports.</span>'}</div></section>`;}
function fullscreenPhoto(){const el=document.getElementById('large-photo');if(el.requestFullscreen)el.requestFullscreen().catch(()=>toast('Fullscreen is unavailable in this window'));else toast('Fullscreen is unavailable in this window');}
function workspaceChecklist(){const s=site(),all=reviewSections(),idx=s.templateSnapshot?customSection:all.findIndex(x=>x.id===section),sec=all[idx],lock=sectionLocked(sec?.id);return `<section class="card working-form"><div class="card-head"><div><h2>${E(sec?.title||'Review & submit')}</h2><p>SITE CHECKLIST · ${sec?'Section '+(idx+1)+' of '+all.length:'Submission and review history'}</p></div><span id="save-state">${lock?'Approved · locked':'Saved on this device'}</span></div><div class="form-body">${s.templateSnapshot?(sec?sec.fields.map(f=>customFieldMarkup(s,f,lock)).join(''):customSubmission(s)):workspaceForm(s,lock)}</div><div class="form-foot"><button class="btn" ${idx<=0?'disabled':''} onclick="openCatalogSection(${idx-1})">Back</button><button class="btn primary" onclick="${idx+1<all.length?'openCatalogSection('+(idx+1)+')':"section='submission';customSection=reviewSections().length;render()"}">Next section ${I('arrow')}</button></div></section>`;}
workspacePage=function(){const s=site();return `<div class="workspace-heading"><div><div class="row wrap"><h1>${E(s.id)}</h1>${badge(s.status)}<span class="small muted">${s.progress}% complete</span></div><p>${E(s.project)} · ${E(s.location)} · ${E(s.engineer)}</p></div><div class="row"><button class="btn" onclick="downloadReport('${E(s.id)}')">${I('export')}Export</button><button class="btn" onclick="showGuide()" aria-label="Workspace guide">${I('help')}</button></div></div>${s.templateSnapshot?`<div class="workspace-branding">${clientLogos(s.templateSnapshot.clients)}<span>${E(s.templateSnapshot.name)} · v${s.templateSnapshot.version}</span></div>`:''}${decisionPanel()}<div class="work-tabs"><button class="${workTab==='photos'?'active':''}" onclick="setWorkTab('photos')">${I('camera')}Photo workspace</button><button class="${workTab==='checklist'?'active':''}" onclick="setWorkTab('checklist')">${I('clipboard')}Checklist & measurements</button></div>${workTab==='photos'?workspacePhotos():workspaceChecklist()}`;};
overview=function(){return `${title(role==='Engineer'?'My work':'Site register','Choose a site to continue its checklist or review the evidence.',`<button class="btn" onclick="exportSites()">Export register</button><button class="btn primary" onclick="newSite()">${I('plus')}New site</button>`)}<section class="card">${siteTable(visibleSites())}</section>`;};
reviewPage=function(){const ss=visibleSites().filter(x=>['Awaiting review','Partially approved'].includes(x.status));return `${title('Review queue','Open a site to inspect evidence and approve all or selected sections.')}<section class="card">${siteTable(ss)}</section>`;};
render=function(){if(view==='website'){document.getElementById('app').innerHTML=marketing();return;}const tabs=[['sites','tower','Sites'],['review','clipboard','Review'],['reports','chart','Reports'],['builder','clipboard','Checklist builder'],['settings','settings','Settings']];const page=({overview,sites:sitesPage,map:mapPage,review:reviewPage,photos:photosPage,reports:reportsPage,projects:projectsPage,team:teamPage,settings:settingsPage,builder:builderPage,workspace:workspacePage}[view]||overview);document.getElementById('app').innerHTML=`<div class="layout-v3 approved-reference"><header class="masthead"><a href="#" class="workspace-brand" onclick="go('overview');return false"><img src="assets/logo-latest.png" alt="iSurvix"><span>SURVEY</span></a><button class="project-picker" onclick="go('projects')">${I('tower')}Telecom survey${I('down')}</button><div class="masthead-right"><button class="iconbtn" aria-label="Find site" onclick="findReferenceSite()">${I('search')}</button><select aria-label="Preview role" onchange="changeRole(this.value)">${['Team leader','Engineer','Admin'].map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select><button class="iconbtn" aria-label="Quick start guide" onclick="showGuide()">${I('help')}</button></div></header><nav class="module-row" aria-label="Main modules">${tabs.map(([v,i,n])=>`<button class="${view===v||(view==='workspace'&&v===(window.activeWizardModule||'sites'))?'active':''}" onclick="go('${v}')">${I(i)}${n}</button>`).join('')}<button onclick="showModuleMenu()">${I('plus')}Add module</button></nav><div class="preview-note"><span>Design preview · Sample data · Changes saved on this device</span><button onclick="go('website')">Public website ${I('external')}</button></div><div class="body-layout ${view==='workspace'&&catalogOpen?'with-catalog':''}">${view==='workspace'?catalog():''}<main class="workspace-main">${view==='workspace'&&!catalogOpen?'<button class="btn" onclick="catalogOpen=true;render()">Show site catalog</button>':''}${page()}</main></div><footer class="layout-footer">iSurvix Survey <span>Interactive preview · Django integration pending</span></footer></div>`;};
// Open directly into the approved photo-led concept, while retaining builder deep links.
if(typeof location==='undefined'||location.hash!=='#builder'){view='workspace';selected=data.sites.find(s=>s.status==='Awaiting review')?.id||data.sites[0].id;section='civil';}
render();
